-- 40_bookkeeping.sql
-- (part A) Bookkeeping tables: staging.news_candidate (the news job's holding table), staging.prompt_run (run log), staging.review_decision (rejected versions),
-- and staging.fact_source (Trace sources and judgement reasons) for the cards written by 10_competitive.sql and 20_client.sql.
-- fact_source rows of tables from the other files (geo, project, market, technology) are written by those files; this file only deletes rows of the tables it owns.
BEGIN;

-- own tables, children first (fact_source: only the rows of tables written by 10_competitive.sql and 20_client.sql)
DELETE FROM staging.fact_source WHERE table_name IN ('client_partner', 'client_partner_product', 'client_partner_relationship', 'client_partner_source', 'client_product', 'client_product_program', 'client_product_source', 'client_product_specification', 'competitive_competitor_location', 'competitive_competitor_moment', 'competitive_competitor_moment_analysis', 'competitive_competitor_moment_source', 'competitive_competitor_swot', 'competitive_leader', 'competitive_leader_record', 'competitive_matchup', 'competitive_matchup_advantage', 'competitive_matchup_source', 'competitive_matchup_specification', 'competitive_news_article', 'competitive_partnership', 'competitive_partnership_evidence', 'competitive_partnership_relationship_detail', 'competitive_patent_classification', 'competitive_patent_filing', 'competitive_patent_portfolio', 'competitive_product', 'competitive_product_evaluation', 'competitive_product_evaluation_spec', 'competitive_product_news', 'competitive_product_program', 'competitive_product_specification', 'competitive_signal', 'competitive_signal_detail', 'competitive_signal_evidence', 'competitive_stock_quote', 'competitive_stock_series');
DELETE FROM staging.review_decision;
DELETE FROM staging.prompt_run;
DELETE FROM staging.news_candidate;

